import { useCallback, useEffect, useMemo, useState } from 'react';
import { Activity, ArrowDownLeft, ArrowDownRight, ArrowLeftRight, ArrowRight, ArrowUpRight, Building2, CalendarDays, Check, CircleHelp, CloudUpload, Download, FileSpreadsheet, Filter, LayoutDashboard, Menu, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Sparkles, Store, WalletCards, X } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { api, clearSession, getUser, jsonRequest, setSession } from './services';

const NAV = [
  { title: 'ESPACIO DE TRABAJO', items: [ ['dashboard','Resumen',LayoutDashboard], ['transactions','Transacciones',ArrowLeftRight], ['consolidation','Consolidación',WalletCards] ] },
  { title: 'ORGANIZACIÓN', items: [ ['companies','Empresas',Building2], ['branches','Sucursales',Store] ] },
  { title: 'DATOS', items: [ ['uploads','Importar datos',CloudUpload], ['reports','Reportes',FileSpreadsheet] ] },
  { title: 'CUENTA', items: [ ['settings','Configuración',Settings] ] },
];
const TITLES = { dashboard:['Resumen financiero','Una mirada clara al desempeño de tu grupo.'], transactions:['Transacciones','Consulta y administra los movimientos del grupo.'], consolidation:['Consolidación','Indicadores consolidados y revisión intercompany.'], companies:['Empresas','Administra las entidades de tu grupo empresarial.'], branches:['Sucursales','Ubicaciones y operación de cada empresa.'], uploads:['Importar datos','Carga movimientos desde archivos CSV o Excel.'], reports:['Reportes','Exporta y comparte la información financiera consolidada.'], settings:['Configuración','El espacio, la moneda, las tasas y quién puede entrar.'] };
const money = (n, currency='GTQ') => new Intl.NumberFormat('es-GT',{style:'currency',currency,maximumFractionDigits:0}).format(Number(n)||0);
const dateFmt = d => d ? new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${String(d).slice(0,10)}T12:00:00`)) : '—';
const cx = (...parts) => parts.filter(Boolean).join(' ');

function App(){
  const [user,setUser] = useState(()=>getUser());
  const [page,setPage] = useState('dashboard');
  const [companies,setCompanies] = useState([]); const [branches,setBranches] = useState([]); const [transactions,setTransactions] = useState([]); const [summary,setSummary] = useState(null); const [audit,setAudit] = useState(null);
  const [busy,setBusy] = useState(true); const [error,setError] = useState(''); const [notice,setNotice] = useState(''); const [query,setQuery] = useState(''); const [modal,setModal] = useState(null); const [mobileOpen,setMobileOpen] = useState(false); const [range,setRange] = useState('Últimos 30 días');
  const [moneda,setMoneda] = useState(''); const [tasas,setTasas] = useState({}); const [serie,setSerie] = useState([]); const [desviaciones,setDesviaciones] = useState(null); const [conteo,setConteo] = useState({});
  const [txRows,setTxRows] = useState([]); const [txTotal,setTxTotal] = useState(0); const [txOffset,setTxOffset] = useState(0); const [txEmpresa,setTxEmpresa] = useState(''); const [txTipo,setTxTipo] = useState('todas');
  const [supportOpen,setSupportOpen] = useState(false); const [profileOpen,setProfileOpen] = useState(false); const [txVersion,setTxVersion] = useState(0);
  const monedaActiva = moneda || 'GTQ';
  const load = useCallback(async()=>{
    if(!getUser()){ setBusy(false); return; }
    setBusy(true); setError('');
    const ventana = range.startsWith('Últimos 30') ? 30 : 180;
    const results = await Promise.allSettled([
      api('/api/empresas'), api('/api/sucursales'), api('/api/transacciones?limit=8&orden=fecha&direccion=desc'),
      api(`/api/consolidacion/resumen?moneda_base=${monedaActiva}`), api('/api/validacion'), api('/api/configuracion'),
      api(`/api/consolidacion/serie?ventana=${ventana}&moneda_base=${monedaActiva}`), api(`/api/consolidacion/desviaciones?dias=30&moneda_base=${monedaActiva}`), api('/api/transacciones/conteo'),
    ]);
    if(results[0].status==='fulfilled') setCompanies(results[0].value); else setError(`No fue posible conectar con el backend: ${results[0].reason.message}`);
    setBranches(results[1].status==='fulfilled'?results[1].value:[]);
    setTransactions(results[2].status==='fulfilled'?results[2].value.items||[]:[]);
    setSummary(results[3].status==='fulfilled'?results[3].value:null);
    setAudit(results[4].status==='fulfilled'?results[4].value:null);
    if(results[5].status==='fulfilled'){ setTasas(results[5].value.tasas||{}); if(!moneda) setMoneda(results[5].value.moneda_base||'GTQ'); }
    setSerie(results[6].status==='fulfilled'?results[6].value.puntos||[]:[]);
    setDesviaciones(results[7].status==='fulfilled'?results[7].value:null);
    setConteo(results[8].status==='fulfilled'?results[8].value.por_empresa||{}:{});
    setBusy(false);
  },[moneda, monedaActiva, range]);
  useEffect(()=>{ const onOut=()=>setUser(null); window.addEventListener('bf-unauthorized', onOut); return ()=>window.removeEventListener('bf-unauthorized', onOut); },[]);
  useEffect(()=>{ if(user) load(); else setBusy(false); },[user, load]);
  useEffect(()=>{ if(!notice) return; const id=setTimeout(()=>setNotice(''),3500); return ()=>clearTimeout(id); },[notice]);
  useEffect(()=>{
    if(!mobileOpen && !profileOpen) return;
    const onKey=e=>{ if(e.key==='Escape'){ setMobileOpen(false); setProfileOpen(false); } };
    window.addEventListener('keydown', onKey);
    return ()=>window.removeEventListener('keydown', onKey);
  },[mobileOpen, profileOpen]);
  useEffect(()=>{
    if(!user || page!=='transactions') return;
    const handle=setTimeout(async()=>{
      const params=new URLSearchParams({limit:'50', offset:String(txOffset), orden:'fecha', direccion:'desc'});
      if(query) params.set('q', query);
      if(txEmpresa) params.set('empresa_id', txEmpresa);
      if(txTipo==='inter') params.set('es_intercompany','S');
      if(txTipo==='operativas') params.set('es_intercompany','N');
      try { const data=await api(`/api/transacciones?${params.toString()}`); setTxRows(data.items||[]); setTxTotal(data.total||0); }
      catch(e){ setError(e.message); }
    },250);
    return ()=>clearTimeout(handle);
  },[user, page, query, txEmpresa, txTipo, txOffset, txVersion]);
  const companyName = id => companies.find(c=>c.id===id)?.nombre || `Empresa ${id}`;
  const currentTitle = TITLES[page];
  const chartData = useMemo(()=>serie.map(p=>({month:new Intl.DateTimeFormat('es-MX',{month:'short'}).format(new Date(`${p.mes}-01T12:00:00`)), ingresos:p.ingresos, gastos:p.gastos})),[serie]);
  const changeMoneda = async(code)=>{ setMoneda(code); if(user?.rol==='admin'){ try { await api('/api/configuracion', jsonRequest('PATCH',{moneda_base:code})); } catch(e){ setError(e.message); } } };
  const createOrUpdate = async(data)=>{
    try { const collection=modal.kind; const base=collection==='company'?'empresas':collection==='branch'?'sucursales':'transacciones'; const endpoint=modal.id?`/api/${base}/${modal.id}`:`/api/${base}`; const body=collection==='company'?{nombre:data.nombre,pais:data.pais,moneda_local:data.moneda_local,activa:data.activa}:collection==='branch'?{empresa_id:Number(data.empresa_id),nombre:data.nombre,ciudad:data.ciudad||null,activa:data.activa}:{empresa_id:Number(data.empresa_id),sucursal_id:data.sucursal_id?Number(data.sucursal_id):null,fecha:data.fecha,cuenta:data.cuenta,descripcion:data.descripcion||null,monto:Number(data.monto),moneda:data.moneda,banco:data.banco||null,categoria:data.categoria||null,es_intercompany:data.es_intercompany,empresa_contraparte_id:data.es_intercompany==='S'&&data.empresa_contraparte_id?Number(data.empresa_contraparte_id):null}; await api(endpoint,jsonRequest(modal.id?'PATCH':'POST',body)); setModal(null);setNotice(modal.id?'Cambios guardados correctamente.':'Registro creado correctamente.'); setTxVersion(v=>v+1); await load(); }
    catch(e){setError(e.message)}
  };
  const remove=async(kind,id)=>{if(!window.confirm('¿Eliminar este registro? Las relaciones asociadas también pueden verse afectadas.'))return;const endpoint=kind==='company'?'empresas':kind==='branch'?'sucursales':'transacciones';try{await api(`/api/${endpoint}/${id}`,{method:'DELETE'});setNotice('Registro eliminado.'); setTxVersion(v=>v+1); await load()}catch(e){setError(e.message)}};
  const exportExcel=async()=>{try{const blob=await api('/api/exportar/excel');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Balance_Consolidado_BalanceFlow.xlsx';a.click();URL.revokeObjectURL(url);setNotice('Reporte descargado.')}catch(e){setError(e.message)}};
  const onPage=p=>{setPage(p);setMobileOpen(false);setQuery('');setTxOffset(0);setProfileOpen(false)};
  if(!user) return <Login onDone={setUser}/>;
  const editar = user.rol==='admin';
  const initials = (user.nombre||'BF').split(' ').slice(0,2).map(w=>w[0]).join('').toUpperCase();
  const nav = (editar ? NAV : NAV.map(group=>({...group, items:group.items.filter(([key])=>key!=='uploads'&&key!=='settings')}))).filter(group=>group.items.length);

  return <div className="app-shell"><a className="skip-link" href="#contenido">Saltar al contenido</a><aside id="menu-lateral" className={cx('sidebar',mobileOpen&&'is-open')} aria-label="Menú">
    <div className="brand"><img src="/assets/images/balanceflow-logo.jpeg" alt="BalanceFlow"/><button className="icon-btn sidebar-close" onClick={()=>setMobileOpen(false)} aria-label="Cerrar menú"><X size={19}/></button></div>
    <div className="workspace"><div className="workspace-mark" aria-hidden="true">BF</div><div className="workspace-copy"><small>ESPACIO DE TRABAJO</small><strong>{user.grupo_nombre||user.nombre||'Tu espacio'}</strong></div></div>
    <nav className="side-nav" aria-label="Secciones">{nav.map(group=><div className="nav-group" key={group.title}><p>{group.title}</p>{group.items.map(([key,label,Icon])=><button key={key} className={cx('nav-item',page===key&&'active')} aria-current={page===key?'page':undefined} onClick={()=>onPage(key)}><Icon size={18} strokeWidth={1.8} aria-hidden="true"/><span>{label}</span>{key==='uploads'&&<span className="nav-dot" aria-hidden="true"/>}</button>)}</div>)}</nav>
    <div className="sidebar-spacer"/><div className="help-card"><div className="help-icon" aria-hidden="true"><CircleHelp size={18}/></div><strong>¿Necesitas ayuda?</strong><span>El mensaje queda registrado.</span><button type="button" onClick={()=>setSupportOpen(true)}>Contactar soporte <ArrowRight size={14} aria-hidden="true"/></button></div>
    <div className="profile"><div className="avatar profile-avatar" aria-hidden="true">{initials}</div><div className="profile-info"><strong>{user.nombre}</strong><span>{user.rol==='admin'?'Administrador':user.rol==='empresa'?'Solo tu empresa':'Lectura'}</span></div><button className="icon-btn profile-more" aria-label="Opciones de perfil" aria-expanded={profileOpen} aria-haspopup="menu" onClick={()=>setProfileOpen(v=>!v)}><MoreHorizontal size={19}/></button>{profileOpen&&<div className="profile-menu" role="menu"><button type="button" role="menuitem" onClick={()=>{clearSession();setUser(null);}}>Cerrar sesión</button></div>}</div>
  </aside>
  {mobileOpen&&<button className="scrim" aria-label="Cerrar menú" onClick={()=>setMobileOpen(false)}/>}
  <main className="main" id="contenido"><header className="topbar"><button className="icon-btn menu-toggle" onClick={()=>setMobileOpen(true)} aria-label="Abrir menú" aria-expanded={mobileOpen} aria-controls="menu-lateral"><Menu size={20}/></button><div className="breadcrumbs"><span>BalanceFlow</span><span className="crumb-slash" aria-hidden="true">/</span><strong>{currentTitle[0]}</strong></div><div className="top-actions"><div className="sync-status" role="status"><span className={cx('sync-dot',error&&'offline')} aria-hidden="true"/>{error?'Sin conexión':'Datos actualizados'}</div><span className="top-divider" aria-hidden="true"/><time className="date-button" dateTime={new Date().toISOString().slice(0,10)}><CalendarDays size={16} aria-hidden="true"/><span>{new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',year:'numeric'}).format(new Date())}</span></time><div className="avatar top-avatar" aria-hidden="true">{initials}</div></div></header>
    <div className="page-content"><div className="page-heading"><div><div className="eyebrow"><Sparkles size={13}/> FINANZAS DE GRUPO</div><h1>{currentTitle[0]}</h1><p>{currentTitle[1]}</p></div>{editar&&page==='transactions'?<button className="button primary" onClick={()=>setModal({kind:'transaction'})}><Plus size={17}/> Nueva transacción</button>:editar&&page==='companies'?<button className="button primary" onClick={()=>setModal({kind:'company'})}><Plus size={17}/> Nueva empresa</button>:editar&&page==='branches'?<button className="button primary" onClick={()=>setModal({kind:'branch'})}><Plus size={17}/> Nueva sucursal</button>:page==='reports'?<button className="button primary" onClick={exportExcel}><Download size={17}/> Exportar reporte</button>:null}</div>
      {error&&<div className="alert error-alert" role="alert"><ShieldCheck size={18} aria-hidden="true"/><div><strong>No se pudo completar la solicitud</strong><span>{error}</span></div><button className="icon-btn" onClick={()=>setError('')} aria-label="Cerrar aviso"><X size={17}/></button></div>}
      {notice&&<div className="toast" role="status"><Check size={16} aria-hidden="true"/>{notice}<button className="icon-btn" onClick={()=>setNotice('')} aria-label="Cerrar aviso"><X size={15}/></button></div>}
      {busy&&<div className="loading-line" role="status"><span aria-hidden="true"/> Cargando información financiera…</div>}
      {page==='dashboard'&&<Dashboard summary={summary} companies={companies} transactions={transactions} chartData={chartData} companyName={companyName} onPage={onPage} range={range} setRange={setRange} audit={audit} moneda={monedaActiva} tasas={tasas} onMoneda={changeMoneda}/>}
      {page==='transactions'&&<Transactions data={txRows} total={txTotal} offset={txOffset} companies={companies} companyName={companyName} query={query} setQuery={value=>{setQuery(value);setTxOffset(0);}} empresaId={txEmpresa} setEmpresaId={value=>{setTxEmpresa(value);setTxOffset(0);}} tipo={txTipo} setTipo={value=>{setTxTipo(value);setTxOffset(0);}} onOffset={setTxOffset} onAdd={editar?()=>setModal({kind:'transaction'}):null} onEdit={editar?t=>setModal({kind:'transaction',id:t.id,item:t}):null} onRemove={editar?id=>remove('transaction',id):null}/>}
      {page==='companies'&&<Companies data={companies} branches={branches} conteo={conteo} onAdd={editar?()=>setModal({kind:'company'}):null} onEdit={editar?c=>setModal({kind:'company',id:c.id,item:c}):null} onRemove={editar?id=>remove('company',id):null}/>}
      {page==='branches'&&<Branches data={branches} companies={companies} onAdd={editar?()=>setModal({kind:'branch'}):null} onEdit={editar?b=>setModal({kind:'branch',id:b.id,item:b}):null} onRemove={editar?id=>remove('branch',id):null}/>}
      {page==='uploads'&&<Uploads companies={companies} onDone={async()=>{await load();setNotice('Archivo procesado. El resumen de carga aparece abajo.')}}/>}
      {page==='consolidation'&&<Consolidation summary={summary} companies={companies} companyName={companyName} transactions={transactions} onExport={exportExcel} audit={audit} desviaciones={desviaciones} moneda={monedaActiva} tasas={tasas} onMoneda={changeMoneda}/>}
      {page==='reports'&&<Reports summary={summary} transactions={transactions} companies={companies} onExport={exportExcel} onPage={onPage}/>}
      {page==='settings'&&editar&&<SettingsPanel companies={companies} onSaved={load} onMoneda={setMoneda}/>}
    </div><footer className="footer"><span>© {new Date().getFullYear()} BalanceFlow</span><span>Hecho para decisiones más claras <span className="footer-heart">✦</span></span></footer><nav className="mobile-nav" aria-label="Navegación principal">{nav.flatMap(group=>group.items).map(([key,label,Icon])=><button key={key} className={cx(page===key&&'active')} aria-current={page===key?'page':undefined} onClick={()=>onPage(key)}><Icon size={18} aria-hidden="true"/><span>{label}</span></button>)}</nav>
  </main>{modal&&<Modal modal={modal} companies={companies} branches={branches} onClose={()=>setModal(null)} onSave={createOrUpdate}/>}{supportOpen&&<SupportModal onClose={()=>setSupportOpen(false)} onSent={()=>{setSupportOpen(false);setNotice('Mensaje enviado al soporte.');}} onError={setError}/>}</div>
}

function Dashboard({summary,companies,transactions,chartData,companyName,onPage,range,setRange,audit,moneda,tasas,onMoneda}){
  const c=summary?.consolidado||{}; const metrics=[['Ingresos del grupo',money(c.total_ingresos,moneda),'Facturación consolidada','up',ArrowUpRight],['Gastos operativos',money(c.total_gastos,moneda),'Operación del grupo','down',ArrowDownRight],['Capital invertido',money(c.total_capital_invertido,moneda),'Base de inversión','',WalletCards],['Empresas activas',String(companies.filter(x=>x.activa).length).padStart(2,'0'),'Entidades del grupo','',Building2]];
  const latest=[...transactions].sort((a,b)=>String(b.fecha).localeCompare(String(a.fecha))).slice(0,5);
  const topCompanies=summary?.por_empresa||[]; const total=Math.max(Number(c.total_ingresos)||0,1);
  let cursor=0; const palette=['#522B5B','#854F6C','#DFB6B2','#FBE4D8']; const donutGradient=topCompanies.length?`conic-gradient(${topCompanies.slice(0,4).map((x,i)=>{const start=cursor;cursor+=Math.max(Number(x.ingresos)||0,0)/total*100;return `${palette[i]} ${start}% ${cursor}%`}).join(', ')}${cursor<100?`, #FBE4D8 ${cursor}% 100%`:''})`:'conic-gradient(#FBE4D8 0 100%)';
  return <><div className="company-strip"><div className="strip-left"><div className="strip-icon"><Building2 size={19}/></div><div><small>VISUALIZANDO</small><strong>Consolidado del grupo</strong></div></div><div className="strip-right"><span>Moneda base</span><select className="currency-chip" value={moneda} onChange={e=>onMoneda(e.target.value)} aria-label="Moneda base">{Object.keys(tasas).length?Object.keys(tasas).map(code=><option key={code}>{code}</option>):<option>{c.moneda_base||moneda}</option>}</select></div></div>
    <section className="kpis">{metrics.map(([label,value,foot,trend,Icon])=><article className="kpi card" key={label}><div className="kpi-top"><span>{label}</span><div className="kpi-icon"><Icon size={18}/></div></div><strong className="kpi-value">{value}</strong><div className="kpi-foot"><span className={cx('trend',trend==='down'&&'trend-warm',!trend&&'trend-neutral')}>{trend==='up'?<ArrowUpRight size={13}/>:trend==='down'?<ArrowDownRight size={13}/>:<Activity size={13}/>} {foot}</span></div></article>)}</section>
    <section className="content-grid"><article className="panel card chart-panel"><div className="panel-head"><div><h2>Desempeño financiero</h2><p>Ingresos y gastos a lo largo del tiempo</p></div><select className="select small-select" value={range} onChange={e=>setRange(e.target.value)}><option>Últimos 30 días</option><option>Últimos 6 meses</option></select></div><div className="chart-legend"><span><i className="legend-income"/>Ingresos</span><span><i className="legend-expense"/>Gastos</span></div><div className="chart-wrap">{chartData.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData} margin={{top:10,right:8,left:-14,bottom:0}}><defs><linearGradient id="incomeFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#522B5B" stopOpacity={0.16}/><stop offset="95%" stopColor="#522B5B" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="rgba(82,43,91,.09)" vertical={false}/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#89798b',fontSize:11}} dy={10}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#89798b',fontSize:10}} tickFormatter={v=>v>=1000000?`${(v/1000000).toFixed(1)}m`:v>=1000?`${Math.round(v/1000)}k`:v}/><Tooltip formatter={v=>money(v,moneda)}/><Area type="monotone" dataKey="ingresos" name="Ingresos" stroke="#522B5B" strokeWidth={2.5} fill="url(#incomeFill)"/><Area type="monotone" dataKey="gastos" name="Gastos" stroke="#DFB6B2" strokeWidth={2.3} fill="transparent"/></AreaChart></ResponsiveContainer>:<EmptyState icon={Activity} title="Aún no hay movimientos" detail="Cuando cargues transacciones, verás aquí la evolución financiera." action="Importar datos" onClick={()=>onPage('uploads')}/>}</div></article>
    <article className="panel card distribution-panel"><div className="panel-head"><div><h2>Ingresos por empresa</h2><p>Participación en el consolidado</p></div><button className="icon-btn" onClick={()=>onPage('consolidation')} aria-label="Ver consolidación"><MoreHorizontal size={19}/></button></div><div className="distribution-body"><div className="donut" style={{background:donutGradient}}><div><small>Total ingresos</small><strong>{money(c.total_ingresos,moneda)}</strong></div></div><div className="company-legend">{topCompanies.slice(0,4).map((x,i)=><div className="legend-row" key={x.empresa_id}><span className={`legend-swatch swatch-${i}`}/><span className="legend-company">{companyName(x.empresa_id)}</span><strong>{Math.round(Number(x.ingresos||0)/total*100)}%</strong></div>)}{!topCompanies.length&&<p className="muted-note">Los ingresos aparecerán cuando haya datos.</p>}</div></div><div className="distribution-foot"><div className="progress-caption"><span>Entidades consolidadas</span><strong>{topCompanies.length} de {companies.length}</strong></div><div className="progress-track"><span style={{width:`${companies.length?Math.min(topCompanies.length/companies.length*100,100):0}%`}}/></div></div></article></section>
    <section className="bottom-grid"><article className="panel card table-panel"><div className="panel-head"><div><h2>Movimientos recientes</h2><p>Últimas transacciones registradas</p></div><button className="text-link" onClick={()=>onPage('transactions')}>Ver todas <ArrowRight size={14}/></button></div>{latest.length?<TransactionTable data={latest} companyName={companyName} compact/>:<EmptyState icon={ArrowLeftRight} title="Sin transacciones recientes" detail="Importa un archivo o registra una transacción para comenzar." action="Registrar movimiento" onClick={()=>onPage('uploads')}/>}</article><article className="panel card activity-panel"><div className="panel-head"><div><h2>Salud del grupo</h2><p>Estado de tus datos financieros</p></div><ShieldCheck size={19} className="healthy-icon"/></div><div className="health-list"><HealthRow icon={Building2} label="Empresas activas" value={`${companies.filter(c=>c.activa).length} de ${companies.length}`} tone="green"/><HealthRow icon={ArrowLeftRight} label="Movimientos cargados" value={`${summary?.total_transacciones_originales??transactions.length} registros`} tone="purple"/><HealthRow icon={ArrowDownLeft} label="Eliminaciones intercompany" value={`${summary?.intercompany?.resumen?.eliminadas||0} pares`} tone="rose"/><HealthRow icon={ShieldCheck} label="Aduana financiera" value={audit?`${audit.resumen?.criticos||0} hallazgos críticos`:'Sin auditoría'} tone="rose"/></div><button className="health-link" onClick={()=>onPage('consolidation')}>Revisar consolidación <ArrowRight size={14}/></button></article></section>
  </>
}
function HealthRow({icon:Icon,label,value,tone}){return <div className="health-row"><div className={`health-icon ${tone}`}><Icon size={16}/></div><div className="health-copy"><strong>{label}</strong><span>{value}</span></div><Check size={15} className="health-check"/></div>}
function EmptyState({icon:Icon,title,detail,action,onClick}){return <div className="empty-state"><div className="empty-icon"><Icon size={20}/></div><strong>{title}</strong><span>{detail}</span>{action&&<button className="text-link" onClick={onClick}>{action} <ArrowRight size={14}/></button>}</div>}
function TransactionTable({data,companyName,compact=false,onEdit,onRemove,onTrace}){return <div className="table-scroll"><table><thead><tr><th>DESCRIPCIÓN</th><th>EMPRESA</th><th>FECHA</th><th>CUENTA</th><th className="align-right">MONTO</th>{!compact&&<th>TIPO</th>}{!compact&&<th>RASTRO</th>}{!compact&&onEdit&&<th/>}</tr></thead><tbody>{data.map(t=><tr key={t.id}><td><div className="tx-description"><span className="tx-mark"><ArrowDownLeft size={14}/></span><div><strong>{t.descripcion||'Movimiento financiero'}</strong><span>{t.categoria||`Referencia #${t.id}`}</span></div></div></td><td><span className="entity-name"><i>{companyName(t.empresa_id).slice(0,1)}</i>{companyName(t.empresa_id)}</span></td><td className="muted-cell">{dateFmt(t.fecha)}</td><td><span className="account-tag">{t.cuenta}</span></td><td className="align-right amount-cell">{money(t.monto,t.moneda||'GTQ')}</td>{!compact&&<td><span className={cx('status-pill',t.es_intercompany==='S'?'status-review':'status-ok')}><i/>{t.es_intercompany==='S'?'Intercompany':'Registrada'}</span></td>}{!compact&&<td><button className="text-link" type="button" onClick={()=>onTrace?.(t)}>Rastrear</button></td>}{!compact&&onEdit&&<td><div className="row-actions"><button className="icon-btn" onClick={()=>onEdit?.(t)} aria-label="Editar transacción"><Settings size={15}/></button><button className="icon-btn" onClick={()=>onRemove?.(t.id)} aria-label="Eliminar transacción"><X size={15}/></button></div></td>}</tr>)}</tbody></table></div>}
function Toolbar({query,setQuery,children}){return <div className="toolbar"><label className="searchbox"><Search size={17} aria-hidden="true"/><span className="sr-only">Buscar</span><input placeholder="Buscar por descripción, cuenta o empresa" value={query} onChange={e=>setQuery(e.target.value)}/><kbd aria-hidden="true">⌘ K</kbd></label>{children}</div>}
const ACCION_AUDITORIA = {creada:'Registrada', importada:'Importada', editada:'Editada', eliminada:'Eliminada'};
const CAMPO_AUDITORIA = {empresa_id:'Empresa', sucursal_id:'Sucursal', fecha:'Fecha', cuenta:'Cuenta', descripcion:'Descripción', monto:'Monto', moneda:'Moneda', monto_base:'Monto en moneda del grupo', banco:'Banco', categoria:'Categoría', es_intercompany:'Intercompany', empresa_contraparte_id:'Contraparte', archivo_origen:'Archivo', fila_origen:'Fila'};
const textoAuditoria = v => v===null||v===undefined||v===''?'—':v==='S'?'Sí':v==='N'?'No':String(v);
const cuando = d => d ? new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(d)) : '—';
function AuditPanel({id,companyName,onClose}){
  const [data,setData]=useState(null);
  const [error,setError]=useState('');
  useEffect(()=>{ let vivo=true; setData(null); setError(''); api(`/api/transacciones/${id}/auditoria`).then(d=>{if(vivo)setData(d);}).catch(e=>{if(vivo)setError(e.message);}); return ()=>{vivo=false}; },[id]);
  const tx = data?.transaccion;
  const origen = data?.eventos?.find(e=>e.detalle?.origen)?.detalle.origen;
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal-card audit-card" role="dialog" aria-modal="true" aria-labelledby="audit-title"><div className="modal-head"><div><span>AUDITORÍA</span><h2 id="audit-title">{tx?.descripcion||(data?.eliminada?'Movimiento eliminado':'Movimiento')}</h2></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Cerrar"><X size={19}/></button></div><div className="modal-body audit-body">{error&&<div className="form-error">{error}</div>}{!data&&!error&&<div className="loading-line"><span/> Leyendo el rastro…</div>}{data&&<><p className="audit-origin">{companyName(tx?.empresa_id||data.eventos[0]?.detalle?.registro?.empresa_id)} · referencia #{data.transaccion_id}{origen?.archivo?` · ${origen.archivo}${origen.fila?`, fila ${origen.fila}`:''}`:' · alta manual'}{data.eliminada?' · este movimiento ya no está en los libros':''}</p><ol className="audit-timeline">{data.eventos.map(evento=><li key={evento.id}><div className="audit-mark"/> <div><strong>{ACCION_AUDITORIA[evento.accion]||evento.accion}</strong><span>{cuando(evento.creado_en)} · {evento.usuario?`${evento.usuario.nombre} (${evento.usuario.email})`:'Sin usuario registrado'}</span>{evento.detalle?.nota&&<p>{evento.detalle.nota}</p>}{evento.detalle?.cambios&&<ul>{Object.entries(evento.detalle.cambios).map(([campo,cambio])=><li key={campo}><b>{CAMPO_AUDITORIA[campo]||campo}</b> {textoAuditoria(cambio.antes)} → {textoAuditoria(cambio.despues)}</li>)}</ul>}{evento.accion!=='editada'&&evento.detalle?.registro&&<ul><li><b>Cuenta</b> {textoAuditoria(evento.detalle.registro.cuenta)}</li><li><b>Fecha</b> {textoAuditoria(evento.detalle.registro.fecha)}</li><li><b>Monto</b> {textoAuditoria(evento.detalle.registro.monto)} {textoAuditoria(evento.detalle.registro.moneda)}</li></ul>}</div></li>)}{!data.eventos.length&&<li><div className="audit-mark"/> <div><strong>Sin hechos</strong><span>Este movimiento no tiene rastro todavía.</span></div></li>}</ol></>}</div></section></div>;
}
function Transactions({data,total,offset,companies,companyName,query,setQuery,empresaId,setEmpresaId,tipo,setTipo,onOffset,onAdd,onEdit,onRemove}){
  const [filtersOpen,setFiltersOpen]=useState(false);
  const [trail,setTrail]=useState(null);
  const pageSize=50; const from=total?offset+1:0; const to=Math.min(offset+data.length,total);
  return <><div className="list-summary"><div><strong>{total}</strong><span>transacciones encontradas</span></div><div className="summary-chips"><span><i className="chip-dot purple-dot"/>{companies.length} empresas</span><span><i className="chip-dot blush-dot"/>{data.filter(x=>x.es_intercompany==='S').length} intercompany en esta página</span></div></div><div className="panel card records-panel"><Toolbar query={query} setQuery={setQuery}><button className="button secondary filter-button" type="button" aria-expanded={filtersOpen} onClick={()=>setFiltersOpen(v=>!v)}><Filter size={16} aria-hidden="true"/> Filtros</button>{onAdd&&<button className="button primary small-button" onClick={onAdd}><Plus size={16}/> Registrar</button>}</Toolbar>{filtersOpen&&<div className="toolbar"><select className="select" value={empresaId} onChange={e=>setEmpresaId(e.target.value)} aria-label="Filtrar por empresa"><option value="">Todas las empresas</option>{companies.map(c=><option key={c.id} value={c.id}>{c.nombre}</option>)}</select><select className="select" value={tipo} onChange={e=>setTipo(e.target.value)} aria-label="Filtrar por tipo"><option value="todas">Todos los tipos</option><option value="inter">Solo intercompany</option><option value="operativas">Solo operativas</option></select></div>}{data.length?<TransactionTable data={data} companyName={companyName} onEdit={onEdit} onRemove={onRemove} onTrace={t=>setTrail(t.id)}/>:<EmptyState icon={ArrowLeftRight} title="No hay transacciones" detail={query||empresaId||tipo!=='todas'?'Prueba con otro término o filtro.':'Registra un movimiento o importa un archivo para comenzar.'}/>}<div className="toolbar"><button className="button secondary" type="button" disabled={offset<=0} onClick={()=>onOffset(Math.max(0,offset-pageSize))}>Anterior</button><span className="muted-note">{from}–{to} de {total}</span><button className="button secondary" type="button" disabled={offset+pageSize>=total} onClick={()=>onOffset(offset+pageSize)}>Siguiente</button></div></div><div className="hint-row"><ShieldCheck size={15}/> Cada movimiento guarda quién lo registró, lo editó o lo eliminó, y de qué archivo salió.</div>{trail&&<AuditPanel id={trail} companyName={companyName} onClose={()=>setTrail(null)}/>}</>
}
function Companies({data,branches,conteo,onAdd,onEdit,onRemove}){return <><div className="entity-grid">{data.map((c,i)=><article className="entity-card card" key={c.id}><div className="entity-card-head"><div className={`entity-logo logo-${i%4}`}>{c.nombre.split(' ').slice(0,2).map(w=>w[0]).join('').slice(0,2).toUpperCase()}</div>{onEdit&&<button className="icon-btn" onClick={()=>onEdit(c)} aria-label="Editar empresa"><MoreHorizontal size={19}/></button>}</div><span className={cx('entity-status',c.activa?'active-status':'inactive-status')}><i/>{c.activa?'Activa':'Inactiva'}</span><h2>{c.nombre}</h2><p>{c.pais} <span>·</span> Moneda local {c.moneda_local}</p><div className="entity-stats"><div><strong>{branches.filter(b=>b.empresa_id===c.id).length}</strong><span>Sucursales</span></div><div><strong>{conteo[c.id]||conteo[String(c.id)]||0}</strong><span>Movimientos</span></div></div><div className="entity-card-actions">{onEdit&&<button className="text-link" onClick={()=>onEdit(c)}>Editar empresa <ArrowRight size={14}/></button>}{onRemove&&<button className="icon-btn danger-icon" onClick={()=>onRemove(c.id)} aria-label="Eliminar empresa"><X size={16}/></button>}</div></article>)}{onAdd&&<button className="entity-add-card" onClick={onAdd}><span><Plus size={19}/></span><strong>Agregar empresa</strong><small>Incorpora una entidad al grupo</small></button>}</div>{!data.length&&<div className="panel card"><EmptyState icon={Building2} title="Tu grupo aún no tiene empresas" detail="Agrega la primera entidad para comenzar a consolidar." action="Agregar empresa" onClick={onAdd}/></div>}</>}
function Branches({data,companies,onAdd,onEdit,onRemove}){return <><div className="list-summary"><div><strong>{data.length}</strong><span>sucursales registradas</span></div><div className="summary-chips"><span><i className="chip-dot green-dot"/>{data.filter(b=>b.activa).length} activas</span></div></div><div className="panel card records-panel"><div className="panel-head panel-table-head"><div><h2>Ubicaciones del grupo</h2><p>Sucursales asociadas a cada empresa</p></div></div>{data.length?<div className="table-scroll"><table><thead><tr><th>SUCURSAL</th><th>EMPRESA</th><th>CIUDAD</th><th>ESTADO</th>{onEdit&&<th/>}</tr></thead><tbody>{data.map(b=><tr key={b.id}><td><span className="branch-cell"><span className="branch-icon"><Store size={16}/></span><strong>{b.nombre}</strong></span></td><td>{companies.find(c=>c.id===b.empresa_id)?.nombre||`Empresa ${b.empresa_id}`}</td><td className="muted-cell">{b.ciudad||'—'}</td><td><span className={cx('status-pill',b.activa?'status-ok':'status-pending')}><i/>{b.activa?'Activa':'Inactiva'}</span></td>{onEdit&&<td><div className="row-actions"><button className="icon-btn" onClick={()=>onEdit(b)} aria-label="Editar sucursal"><Settings size={15}/></button>{onRemove&&<button className="icon-btn" onClick={()=>onRemove(b.id)} aria-label="Eliminar sucursal"><X size={15}/></button>}</div></td>}</tr>)}</tbody></table></div>:<EmptyState icon={Store} title="Sin sucursales registradas" detail="Agrega sucursales para organizar los movimientos por ubicación." action={onAdd?'Nueva sucursal':undefined} onClick={onAdd||undefined}/>}</div></>}
function Uploads({companies,onDone}){const [file,setFile]=useState(null);const [company,setCompany]=useState('');const [currency,setCurrency]=useState('GTQ');const [drag,setDrag]=useState(false);const [loading,setLoading]=useState(false);const [result,setResult]=useState(null);const [localError,setLocalError]=useState('');
 const submit=async()=>{if(!file||!company){setLocalError('Selecciona una empresa y un archivo para continuar.');return}setLoading(true);setLocalError('');setResult(null);const form=new FormData();form.append('archivo',file);form.append('empresa_id',company);form.append('moneda_default',currency);try{const data=await api('/api/uploads/excel',{method:'POST',body:form});setResult(data);onDone()}catch(e){setLocalError(e.message)}finally{setLoading(false)}};
 return <><div className="upload-layout"><div className="panel card upload-panel"><div className="panel-head"><div><h2>Sube tus movimientos</h2><p>El sistema detecta y normaliza automáticamente las columnas.</p></div><div className="upload-head-icon"><CloudUpload size={19}/></div></div><label className="form-label">Empresa destino</label><select className="select upload-select" value={company} onChange={e=>setCompany(e.target.value)}><option value="">Selecciona una empresa</option>{companies.map(c=><option key={c.id} value={c.id}>{c.nombre}</option>)}</select><label className="form-label">Moneda por defecto <span>Se usa si el archivo no incluye una columna de moneda.</span></label><input className="select upload-select" value={currency} onChange={e=>setCurrency(e.target.value.toUpperCase().slice(0,3))} maxLength={3} aria-label="Moneda por defecto"/><div className={cx('dropzone',drag&&'dragging',file&&'has-file')} onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={e=>{e.preventDefault();setDrag(false);const f=e.dataTransfer.files?.[0];if(f)setFile(f)}}><input type="file" accept=".csv,.xlsx,.xls" onChange={e=>setFile(e.target.files?.[0]||null)}/><div className="drop-icon">{file?<FileSpreadsheet size={21}/>:<CloudUpload size={21}/>}</div><strong>{file?file.name:'Arrastra tu archivo aquí'}</strong><span>{file?`${(file.size/1024).toFixed(0)} KB · Listo para importar`:'o haz clic para buscar en tu dispositivo'}</span><small>CSV, XLSX o XLS · Máximo recomendado 10 MB</small>{file&&<button className="remove-file" onClick={e=>{e.preventDefault();setFile(null)}}>Quitar archivo</button>}</div>{localError&&<p className="form-error">{localError}</p>}<button className="button primary upload-submit" onClick={submit} disabled={loading||!file||!company}>{loading?<span className="spinner"/>:<CloudUpload size={17}/>} {loading?'Procesando archivo…':'Importar transacciones'}</button></div><aside className="upload-aside"><div className="aside-tip"><div className="tip-icon"><Sparkles size={18}/></div><h3>Importación inteligente</h3><p>BalanceFlow reconoce distintos nombres de columnas y formatos de fecha y monto automáticamente.</p></div><div className="panel card columns-card"><h3>Columnas reconocidas</h3><p>Estos campos ayudan a obtener mejores resultados.</p>{[['fecha','Obligatoria'],['cuenta','Obligatoria'],['monto','Obligatoria'],['moneda','Opcional'],['descripcion','Opcional'],['categoria','Opcional']].map(([x,y])=><div className="column-row" key={x}><code>{x}</code><span>{y==='Obligatoria'?<b>Requerida</b>:y}</span></div>)}</div></aside></div>{result&&<div className="panel card upload-result"><div className="result-heading"><div className="result-success"><Check size={18}/></div><div><h2>Importación completada</h2><p>{result.archivo} · {company?companies.find(c=>c.id===Number(company))?.nombre:''}</p></div><span className="status-pill status-ok"><i/>Correcto</span></div><div className="result-stats">{[['Filas leídas',result.filas_leidas],['Válidas',result.filas_validas],['Descartadas',result.filas_descartadas],['Registradas',result.transacciones_insertadas]].map(([k,v])=><div key={k}><small>{k}</small><strong>{v}</strong></div>)}</div>{result.columnas_detectadas?.length>0&&<p className="detected-columns">Campos identificados: {result.columnas_detectadas.join(' · ')}</p>}{result.validacion&&<p className="detected-columns">Aduana: {result.validacion.estado} · {result.filas_en_cuarentena||0} filas en cuarentena · {result.validacion.resumen?.total_alertas||0} alertas</p>}</div>}</>}
function Consolidation({summary,companies,companyName,transactions,onExport,audit,desviaciones,moneda,tasas,onMoneda}){const c=summary?.consolidado||{};const inter=summary?.intercompany;const [trace,setTrace]=useState(null);const [traceBusy,setTraceBusy]=useState(false);const [traceError,setTraceError]=useState('');const [trail,setTrail]=useState(null);const loadTrace=async(comp)=>{setTraceBusy(true);setTraceError('');try{setTrace(await api(`/api/trazabilidad/${comp}`))}catch(e){setTrace(null);setTraceError(e.message)}finally{setTraceBusy(false)}};return <><div className="company-strip"><div className="strip-left"><div className="strip-icon"><WalletCards size={19}/></div><div><small>ENTIDADES EN EL GRUPO</small><strong>{c.empresas_incluidas?.length||0} empresas consolidadas</strong></div></div><div className="strip-right"><span>Moneda de consolidación</span><select className="currency-chip" value={moneda} onChange={e=>onMoneda(e.target.value)} aria-label="Moneda de consolidación">{Object.keys(tasas).length?Object.keys(tasas).map(code=><option key={code}>{code}</option>):<option>{c.moneda_base||moneda}</option>}</select></div></div><div className="consolidation-hero card"><div><span className="hero-eyebrow"><span/> CONSOLIDADO ACTUAL</span><h2>Resumen del grupo</h2><p>Indicadores financieros calculados sobre las transacciones disponibles.</p></div><button className="button secondary" onClick={onExport}><Download size={16}/> Descargar Excel</button></div><div className="kpis consolidation-kpis">{[['Ingresos',money(c.total_ingresos,c.moneda_base||moneda)],['Gastos',money(c.total_gastos,c.moneda_base||moneda)],['NOPAT',money(c.total_nopat,c.moneda_base||moneda)],['ROIC del grupo',`${(Number(c.roic_grupo||0)*100).toFixed(1)}%`],['Capital invertido',money(c.total_capital_invertido,c.moneda_base||moneda)],['EVA',money(c.eva_grupo,c.moneda_base||moneda)]].map(([k,v],i)=><article className="kpi card" key={k}><div className="kpi-top"><span>{k}</span><div className="kpi-icon"><WalletCards size={17}/></div></div><strong className="kpi-value">{v}</strong><div className="kpi-foot"><span className="kpi-context">{i===3?'Retorno sobre capital':'Moneda base '+(c.moneda_base||'GTQ')}</span></div></article>)}</div><div className="panel card records-panel"><div className="panel-head panel-table-head"><div><h2>Rendimiento por empresa</h2><p>Indicadores operativos de cada entidad</p></div></div>{summary?.por_empresa?.length?<div className="table-scroll"><table><thead><tr><th>EMPRESA</th><th>INGRESOS</th><th>GASTOS</th><th>CAPITAL INVERTIDO</th><th>ROIC</th><th>EVA</th></tr></thead><tbody>{summary.por_empresa.map((x,i)=><tr key={x.empresa_id}><td><span className="entity-name"><i className={`company-mini mini-${i%4}`}>{companyName(x.empresa_id).slice(0,1)}</i>{companyName(x.empresa_id)}</span></td><td className="amount-cell">{money(x.ingresos,c.moneda_base)}</td><td className="amount-cell">{money(x.gastos,c.moneda_base)}</td><td className="amount-cell">{money(x.capital_invertido,c.moneda_base)}</td><td><span className="roic-tag">{(Number(x.roic||0)*100).toFixed(1)}%</span></td><td className="amount-cell">{money(x.eva,c.moneda_base)}</td></tr>)}</tbody></table></div>:<EmptyState icon={WalletCards} title="Aún no hay datos para consolidar" detail="Carga transacciones y vuelve a consultar el consolidado."/>}</div><div className="intercompany-grid"><div className="panel card intercompany-card"><div className="intercompany-icon"><ArrowLeftRight size={18}/></div><div><span>PARES ELIMINADOS</span><strong>{inter?.resumen?.eliminadas||0}</strong><p>Transacciones internas conciliadas y eliminadas</p></div></div><div className={cx('panel card intercompany-card',inter?.resumen?.descuadres>0&&'warning-panel')}><div className="intercompany-icon"><ShieldCheck size={18}/></div><div><span>DESCUADRES DETECTADOS</span><strong>{inter?.resumen?.descuadres||0}</strong><p>Requieren revisión de contraparte o importe</p></div></div><div className="panel card intercompany-card"><div className="intercompany-icon"><ArrowLeftRight size={18}/></div><div><span>MOVIMIENTOS INCLUIDOS</span><strong>{summary?.total_transacciones_limpias||transactions.length}</strong><p>Registros tras la conciliación</p></div></div></div>{inter?.descuadres?.length>0&&<div className="panel card records-panel"><div className="panel-head panel-table-head"><div><h2>Transacciones para revisar</h2><p>Movimientos intercompany sin espejo confirmado</p></div></div><div className="table-scroll"><table><thead><tr><th>TIPO</th><th>DETALLE</th><th>EMPRESA</th><th>IMPORTE</th></tr></thead><tbody>{inter.descuadres.map((d,i)=><tr key={i}><td><span className="status-pill status-pending"><i/>{d.tipo}</span></td><td>{d.mensaje}</td><td>{companyName(d.datos?.empresa_id)}</td><td className="amount-cell">{money(d.datos?.monto_base??d.datos?.monto,d.datos?.moneda||c.moneda_base)}</td></tr>)}</tbody></table></div></div>}<div className="panel card records-panel" style={{marginTop:14}}><div className="panel-head panel-table-head"><div><h2>Desviaciones</h2><p>{desviaciones?.total_cambios?`${desviaciones.total_cambios} cambios frente a los 30 días anteriores.`:'Sin variación relevante en los últimos 30 días.'}</p></div></div>{desviaciones?.explicaciones?.length>0&&<div className="table-scroll"><table><thead><tr><th>CAMPO</th><th>ANTERIOR</th><th>ACTUAL</th><th>VARIACIÓN</th></tr></thead><tbody>{desviaciones.explicaciones.map(d=><tr key={d.campo}><td>{d.campo}</td><td>{d.valor_anterior}</td><td>{d.valor_actual}</td><td>{d.direccion} {d.variacion_pct}%</td></tr>)}</tbody></table></div>}</div><div className="panel card records-panel" style={{marginTop:14}}><div className="panel-head panel-table-head"><div><h2>Trazabilidad</h2><p>{audit?`Aduana: ${audit.estado}. ${audit.resumen?.criticos||0} hallazgos críticos en los datos cargados.`:'Detalle de las cifras consolidadas.'}</p></div></div><div className="toolbar">{['ingresos','gastos','activos','pasivos'].map(comp=><button type="button" key={comp} className="button secondary small-button" onClick={()=>loadTrace(comp)} disabled={traceBusy}>{comp}</button>)}</div>{traceError&&<p className="form-error">{traceError}</p>}{traceBusy&&<div className="loading-line"><span/> Consultando el origen de la cifra…</div>}{trace&&<div className="table-scroll"><table><thead><tr><th>EMPRESA</th><th>CUENTA</th><th>FECHA</th><th>MONTO ORIGINAL</th><th>MONEDA DEL GRUPO</th><th>ORIGEN</th><th/></tr></thead><tbody>{trace.registros.map(r=><tr key={`${r.id}-${r.cuenta}`}><td>{companyName(r.empresa_id)}</td><td><span className="account-tag">{r.cuenta}</span></td><td className="muted-cell">{dateFmt(r.fecha)}</td><td className="amount-cell">{money(r.monto_original,r.moneda||'GTQ')}</td><td className="amount-cell">{money(r.monto_gtq,moneda||'GTQ')}</td><td className="muted-cell">{r.archivo_origen?`${r.archivo_origen}${r.fila_origen?` · fila ${r.fila_origen}`:''}`:'Alta manual'}</td><td><button className="text-link" type="button" onClick={()=>setTrail(r.id)}>Rastrear</button></td></tr>)}{!trace.registros.length&&<tr><td colSpan={7}>No hay registros para este componente.</td></tr>}</tbody></table></div>}</div>{trail&&<AuditPanel id={trail} companyName={companyName} onClose={()=>setTrail(null)}/>}</>}
function Reports({summary,transactions,companies,onExport,onPage}){return <><div className="report-banner card"><div className="report-art"><FileSpreadsheet size={26}/></div><div className="report-copy"><span>REPORTE DEL GRUPO</span><h2>Balance consolidado</h2><p>Descarga tus movimientos e indicadores en un archivo Excel listo para compartir.</p><div className="report-meta"><span><Check size={14}/> Indicadores por empresa</span><span><Check size={14}/> Movimientos normalizados</span></div></div><button className="button primary" onClick={onExport}><Download size={17}/> Descargar Excel</button></div><div className="report-tiles"><article className="panel card report-tile"><div className="tile-icon"><ArrowLeftRight size={18}/></div><small>REGISTROS DISPONIBLES</small><strong>{(summary?.total_transacciones_originales??transactions.length).toLocaleString('es-MX')}</strong><span>Movimientos financieros</span><button className="text-link" onClick={()=>onPage('transactions')}>Ver transacciones <ArrowRight size={14}/></button></article><article className="panel card report-tile"><div className="tile-icon"><Building2 size={18}/></div><small>ENTIDADES DEL GRUPO</small><strong>{companies.length}</strong><span>{summary?.por_empresa?.length||0} incluidas en el consolidado</span><button className="text-link" onClick={()=>onPage('companies')}>Ver empresas <ArrowRight size={14}/></button></article><article className="panel card report-tile"><div className="tile-icon"><WalletCards size={18}/></div><small>MONEDA BASE</small><strong>{summary?.consolidado?.moneda_base||'GTQ'}</strong><span>{summary?.intercompany?.resumen?.eliminadas||0} pares intercompany eliminados</span><button className="text-link" onClick={()=>onPage('consolidation')}>Ver consolidación <ArrowRight size={14}/></button></article></div><div className="hint-row"><ShieldCheck size={15}/> El archivo se genera con los datos disponibles al momento de la descarga.</div></>}
function Modal({modal,companies,branches,onClose,onSave}){const item=modal.item||{};const [form,setForm]=useState({nombre:item.nombre||'',pais:item.pais||'',moneda_local:item.moneda_local||'GTQ',empresa_id:item.empresa_id||companies[0]?.id||'',ciudad:item.ciudad||'',fecha:item.fecha||new Date().toISOString().slice(0,10),cuenta:item.cuenta||'',descripcion:item.descripcion||'',monto:item.monto??'',moneda:item.moneda||'GTQ',categoria:item.categoria||'',banco:item.banco||'',sucursal_id:item.sucursal_id||'',es_intercompany:item.es_intercompany||'N',empresa_contraparte_id:item.empresa_contraparte_id||'',activa:item.activa??true});const set=(k,v)=>setForm(f=>({...f,[k]:v}));const kind=modal.kind;const title=kind==='company'?'empresa':kind==='branch'?'sucursal':'transacción';const [validation,setValidation]=useState('');const submit=e=>{e.preventDefault();if(kind==='transaction'&&(!form.empresa_id||!form.fecha||!form.cuenta||form.monto==='')){setValidation('Completa los campos obligatorios para continuar.');return}onSave(form)};
 const field=(label,key,props={})=><label className="modal-field"><span>{label}</span><input value={form[key]} onChange={e=>set(key,e.target.value)} {...props}/></label>;
 return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title" onSubmit={submit}><div className="modal-head"><div><span>{modal.id?'EDITAR':'NUEVO REGISTRO'}</span><h2 id="modal-title">{modal.id?'Editar':'Nueva'} {title}</h2></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Cerrar"><X size={19}/></button></div><div className="modal-body">{kind==='company'?<>{field('Nombre de la empresa','nombre',{required:true,maxLength:120,placeholder:'Ej. Grupo empresarial'})}{field('País','pais',{required:true,maxLength:60,placeholder:'País'})}<label className="modal-field"><span>Moneda local</span><input value={form.moneda_local} onChange={e=>set('moneda_local',e.target.value.toUpperCase().slice(0,3))} maxLength={3} required placeholder="GTQ"/></label><label className="checkbox-field"><input type="checkbox" checked={form.activa} onChange={e=>set('activa',e.target.checked)}/> Empresa activa</label></>:kind==='branch'?<><label className="modal-field"><span>Empresa</span><select className="select" value={form.empresa_id} onChange={e=>set('empresa_id',e.target.value)} required>{companies.map(x=><option key={x.id} value={x.id}>{x.nombre}</option>)}</select></label>{field('Nombre de la sucursal','nombre',{required:true,maxLength:120,placeholder:'Ej. Sucursal central'})}{field('Ciudad','ciudad',{maxLength:80,placeholder:'Ciudad'})}<label className="checkbox-field"><input type="checkbox" checked={form.activa} onChange={e=>set('activa',e.target.checked)}/> Sucursal activa</label></>:<><label className="modal-field"><span>Empresa</span><select className="select" value={form.empresa_id} onChange={e=>set('empresa_id',e.target.value)} required>{companies.map(x=><option key={x.id} value={x.id}>{x.nombre}</option>)}</select></label><div className="form-row">{field('Fecha','fecha',{required:true,type:'date'})}{field('Cuenta','cuenta',{required:true,maxLength:20,placeholder:'4100'})}</div>{field('Descripción','descripcion',{maxLength:255,placeholder:'Descripción del movimiento'})}<div className="form-row">{field('Monto','monto',{required:true,type:'number',step:'any',placeholder:'0.00'})}<label className="modal-field"><span>Moneda</span><input value={form.moneda} onChange={e=>set('moneda',e.target.value.toUpperCase().slice(0,3))} maxLength={3} required placeholder="GTQ"/></label></div><div className="form-row">{field('Categoría','categoria',{maxLength:80,placeholder:'Ventas'})}<label className="modal-field"><span>Sucursal</span><select className="select" value={form.sucursal_id} onChange={e=>set('sucursal_id',e.target.value)}><option value="">Sin sucursal</option>{branches.filter(b=>Number(b.empresa_id)===Number(form.empresa_id)).map(b=><option key={b.id} value={b.id}>{b.nombre}</option>)}</select></label></div><label className="checkbox-field"><input type="checkbox" checked={form.es_intercompany==='S'} onChange={e=>set('es_intercompany',e.target.checked?'S':'N')}/> Es movimiento intercompany</label>{form.es_intercompany==='S'&&<label className="modal-field"><span>Empresa contraparte</span><select className="select" value={form.empresa_contraparte_id} onChange={e=>set('empresa_contraparte_id',e.target.value)}><option value="">Selecciona la contraparte</option>{companies.filter(c=>c.id!==Number(form.empresa_id)).map(c=><option value={c.id} key={c.id}>{c.nombre}</option>)}</select></label>}</>}{validation&&<div className="form-error">{validation}</div>}</div><div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Cancelar</button><button className="button primary" type="submit"><Check size={16}/>{modal.id?'Guardar cambios':'Crear '+title}</button></div></form></div>
}

function SettingsPanel({companies,onSaved,onMoneda}){
  const [form,setForm]=useState(null); const [tasaNueva,setTasaNueva]=useState({moneda:'',tasa:''}); const [acceso,setAcceso]=useState({nombre:'',email:'',password:'',rol:'empresa',empresa_id:companies[0]?.id||''}); const [aviso,setAviso]=useState(''); const [error,setError]=useState('');
  useEffect(()=>{ api('/api/configuracion').then(data=>setForm({nombre_grupo:data.nombre_grupo,moneda_base:data.moneda_base,wacc:String(data.wacc),tasas:{...data.tasas}})).catch(e=>setError(e.message)); },[]);
  if(!form) return <div className="loading-line"><span/> Cargando configuración…</div>;
  const guardar=async(e)=>{e.preventDefault(); setError(''); try{ const data=await api('/api/configuracion', jsonRequest('PATCH',{nombre_grupo:form.nombre_grupo, moneda_base:form.moneda_base, wacc:Number(form.wacc), tasas:form.tasas})); setForm({nombre_grupo:data.nombre_grupo, moneda_base:data.moneda_base, wacc:String(data.wacc), tasas:{...data.tasas}}); onMoneda(data.moneda_base); setAviso('Configuración guardada.'); onSaved(); }catch(err){ setError(err.message);} };
  const crearAcceso=async(e)=>{e.preventDefault(); setError(''); try{ await api('/api/auth/usuarios', jsonRequest('POST',{nombre:acceso.nombre, email:acceso.email, password:acceso.password, rol:acceso.rol, empresa_id:acceso.rol==='empresa'?Number(acceso.empresa_id):null})); setAcceso({nombre:'',email:'',password:'',rol:'empresa',empresa_id:companies[0]?.id||''}); setAviso('Acceso creado. Esa persona ya puede entrar con su correo.'); }catch(err){ setError(err.message);} };
  return <div className="upload-layout"><form className="panel card upload-panel" onSubmit={guardar}><div className="panel-head"><div><h2>Tu espacio</h2><p>Estos valores son de tu cuenta. No cambian los de otros clientes.</p></div></div><label className="form-label">Nombre del espacio</label><input className="select upload-select" value={form.nombre_grupo} onChange={e=>setForm({...form,nombre_grupo:e.target.value})} required maxLength={120}/><label className="form-label">Moneda base</label><input className="select upload-select" value={form.moneda_base} onChange={e=>setForm({...form,moneda_base:e.target.value.toUpperCase().slice(0,3)})} maxLength={3} required/><label className="form-label">WACC <span>Entre 0 y 1. 0.10 es 10%.</span></label><input className="select upload-select" type="number" min="0" max="1" step="0.0001" value={form.wacc} onChange={e=>setForm({...form,wacc:e.target.value})} required/><label className="form-label">Tasas <span>Unidades de GTQ por cada moneda. Puedes agregar cualquiera.</span></label>{Object.entries(form.tasas).map(([codigo,valor])=><div className="form-row" key={codigo}><input value={codigo} readOnly/><input type="number" step="any" value={valor} onChange={e=>setForm({...form,tasas:{...form.tasas,[codigo]:Number(e.target.value)}})}/></div>)}<div className="form-row"><input placeholder="PEN" value={tasaNueva.moneda} maxLength={3} onChange={e=>setTasaNueva({...tasaNueva,moneda:e.target.value.toUpperCase()})} aria-label="Nueva moneda"/><input type="number" step="any" placeholder="2.10" value={tasaNueva.tasa} onChange={e=>setTasaNueva({...tasaNueva,tasa:e.target.value})} aria-label="Tasa de la nueva moneda"/></div><button type="button" className="button secondary" onClick={()=>{ if(tasaNueva.moneda.length===3&&tasaNueva.tasa!==''){ setForm({...form,tasas:{...form.tasas,[tasaNueva.moneda]:Number(tasaNueva.tasa)}}); setTasaNueva({moneda:'',tasa:''}); } }}>Agregar moneda</button>{error&&<p className="form-error">{error}</p>}{aviso&&<p className="detected-columns">{aviso}</p>}<button className="button primary upload-submit" type="submit">Guardar configuración</button></form><form className="panel card upload-panel" onSubmit={crearAcceso}><div className="panel-head"><div><h2>Accesos</h2><p>Crea un administrador, un lector de todo el espacio o alguien que solo vea una empresa.</p></div></div><label className="form-label">Nombre</label><input className="select upload-select" value={acceso.nombre} onChange={e=>setAcceso({...acceso,nombre:e.target.value})} required/><label className="form-label">Correo</label><input className="select upload-select" type="email" value={acceso.email} onChange={e=>setAcceso({...acceso,email:e.target.value})} required/><label className="form-label">Contraseña</label><input className="select upload-select" type="password" minLength={8} value={acceso.password} onChange={e=>setAcceso({...acceso,password:e.target.value})} required/><label className="form-label">Alcance</label><select className="select upload-select" value={acceso.rol} onChange={e=>setAcceso({...acceso,rol:e.target.value})}><option value="empresa">Una empresa</option><option value="lector">Todo el espacio, solo lectura</option><option value="admin">Todo el espacio, puede configurar</option></select>{acceso.rol==='empresa'&&<><label className="form-label">Empresa</label><select className="select upload-select" value={acceso.empresa_id} onChange={e=>setAcceso({...acceso,empresa_id:e.target.value})} required>{companies.map(c=><option key={c.id} value={c.id}>{c.nombre}</option>)}</select></>}<button className="button primary upload-submit" type="submit">Crear acceso</button></form></div>;
}
function Login({onDone}){
  const [modo,setModo]=useState('entrar');
  const [nombre,setNombre]=useState('');
  const [grupo,setGrupo]=useState('');
  const [email,setEmail]=useState('');
  const [password,setPassword]=useState('');
  const [error,setError]=useState('');
  const [loading,setLoading]=useState(false);
  const crear = modo==='crear';
  const submit=async(e)=>{
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const data = crear
        ? await api('/api/auth/registro', jsonRequest('POST',{nombre,email,password,nombre_grupo:grupo}))
        : await api('/api/auth/login', jsonRequest('POST',{email,password}));
      setSession(data);
      onDone(data.usuario);
    } catch(err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };
  return (
    <div className="auth-screen">
      <section className="auth-brand">
        <img src="/assets/images/balanceflow-logo.jpeg" alt="BalanceFlow"/>
        <p className="auth-kicker">Servicio de consolidación</p>
        <h1>Cada grupo entra a su propio espacio.</h1>
        <p>Crea tu cuenta, define empresas, monedas y quién puede ver cada una. Lo que cargues no se mezcla con otros clientes.</p>
      </section>
      <section className="auth-panel">
        <form className="auth-card" onSubmit={submit}>
          <div className="auth-switch" role="tablist" aria-label="Tipo de acceso">
            <button type="button" role="tab" aria-selected={!crear} className={!crear?'active':''} onClick={()=>{setModo('entrar');setError('');}}>Entrar</button>
            <button type="button" role="tab" aria-selected={crear} className={crear?'active':''} onClick={()=>{setModo('crear');setError('');}}>Crear cuenta</button>
          </div>
          <h2>{crear?'Abre un espacio nuevo':'Bienvenido de nuevo'}</h2>
          <p className="auth-lead">{crear?'Empiezas sin empresas. La configuración queda a tu cargo.':'Usa el correo con el que registraste tu espacio.'}</p>
          {crear&&<label className="auth-field"><span>Tu nombre</span><input value={nombre} onChange={e=>setNombre(e.target.value)} required autoComplete="name" placeholder="Ana Ruiz"/></label>}
          {crear&&<label className="auth-field"><span>Nombre del espacio</span><input value={grupo} onChange={e=>setGrupo(e.target.value)} required placeholder="Grupo Andino"/></label>}
          <label className="auth-field"><span>Correo</span><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="username" placeholder="ana@empresa.com"/></label>
          <label className="auth-field"><span>Contraseña</span><input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={8} autoComplete={crear?'new-password':'current-password'} placeholder="Mínimo 8 caracteres"/></label>
          {error&&<div className="auth-error" role="alert">{error}</div>}
          <button className="button primary auth-submit" type="submit" disabled={loading}>{loading?'Un momento…':crear?'Crear espacio':'Entrar'}</button>
        </form>
      </section>
    </div>
  );
}
function SupportModal({onClose,onSent,onError}){
  const [mensaje,setMensaje]=useState(''); const [loading,setLoading]=useState(false);
  const submit=async(e)=>{e.preventDefault(); setLoading(true); try{ await api('/api/soporte', jsonRequest('POST',{mensaje})); onSent(); } catch(err){ onError(err.message); } finally{ setLoading(false);} };
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal-card" role="dialog" aria-modal="true" aria-labelledby="soporte-title" onSubmit={submit}><div className="modal-head"><div><span>SOPORTE</span><h2 id="soporte-title">Escribe tu mensaje</h2></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Cerrar"><X size={19}/></button></div><div className="modal-body"><label className="modal-field"><span>Mensaje</span><input value={mensaje} onChange={e=>setMensaje(e.target.value)} required minLength={5} maxLength={1000} placeholder="¿En qué podemos ayudarte?"/></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Cancelar</button><button className="button primary" type="submit" disabled={loading}>{loading?'Enviando…':'Enviar'}</button></div></form></div>;
}

export default App;
